from pathlib import Path
p=Path('outputs/index.html');s=p.read_text(encoding='utf-8')
s=s.replace("['H','Medkit'","['l','Sweeping laser ↔','#ff4d68','↔'],['m','Sweeping laser ↕','#ff4d68','↕'],['H','Medkit'",1)
s=s.replace("{name:'Enemies',tiles:['E','7','8']},","{name:'Enemies',tiles:['E','7','8']},\n{name:'Hazards',tiles:['l','m']},",1)
s=s.replace('enemies=[], pickups=[]','lasers=[], enemies=[], pickups=[]',1)
s=s.replace('world=level.grid.map(r=>r.slice());enemies=[]','world=level.grid.map(r=>r.slice());lasers=[];enemies=[]',1)
s=s.replace("total=enemies.length;kills=0;", "world.forEach((r,y)=>r.forEach((t,x)=>{if(t==='l'||t==='m'){let laser=makeLaser(x,y,t);if(laser)lasers.push(laser)}}));total=enemies.length;kills=0;",1)
helper='''
function makeLaser(x,y,type){let horizontal=type==='l',along=horizontal?x:y,cross=horizontal?y:x,at=(a,b)=>horizontal?world[b]?.[a]:world[a]?.[b],limit=horizontal?world[0].length:world.length,crossLimit=horizontal?world.length:world[0].length,solid=t=>wallTiles.includes(t)||['3','4','5','O','R','B','Y','C','D','G','I','K','L','M','N','U','W','J','F','V','T','9'].includes(t)||!!crawlOpenings[t];let lo=along,hi=along;while(lo>0&&!solid(at(lo-1,cross)))lo--;while(hi<limit-1&&!solid(at(hi+1,cross)))hi++;if(!wallTiles.includes(at(lo-1,cross))||!wallTiles.includes(at(hi+1,cross)))return null;let fits=b=>wallTiles.includes(at(lo-1,b))&&wallTiles.includes(at(hi+1,b))&&Array.from({length:hi-lo+1},(_,i)=>at(lo+i,b)).every(t=>t&&!solid(t)),min=cross,max=cross;while(min>1&&fits(min-1))min--;while(max<crossLimit-2&&fits(max+1))max++;return {horizontal,lo,hi,min:min+.5,max:max+.5,pos:cross+.5,direction:1,cooldown:0,height:.95}}
function updateLasers(dt,previousX,previousY){for(let l of lasers){let old=l.pos;l.cooldown=Math.max(0,l.cooldown-dt);if(l.max>l.min){l.pos+=l.direction*1.2*dt;while(l.pos>l.max||l.pos<l.min){if(l.pos>l.max){l.pos=2*l.max-l.pos;l.direction=-1}else{l.pos=2*l.min-l.pos;l.direction=1}}}let along=l.horizontal?player.x:player.y,cross=l.horizontal?player.y:player.x,previous=l.horizontal?previousY:previousX,a=previous-old,b=cross-l.pos,crossed=Math.abs(b)<.2||a*b<=0;if(l.cooldown===0&&crossed&&along>=l.lo-.15&&along<=l.hi+1.15&&(player.height||0)<l.height+.04&&playerBodyHeight()>l.height-.04){player.hp=Math.max(0,player.hp-15);hurt=.3;l.cooldown=.75;sound(110,.13,'sawtooth',.035)}}}
function renderLasers(v){for(let l of lasers){let mid=(l.lo+l.hi+1)/2,length=l.hi-l.lo+1,x=l.horizontal?mid:l.pos,z=l.horizontal?l.pos:mid;box(v,x,l.height,z,l.horizontal?length:.025,.025,l.horizontal?.025:length,[1,.08,.18]);box(v,x,l.height,z,l.horizontal?length:.055,.055,l.horizontal?.055:length,[.65,.035,.075]);for(let end of [l.lo+.04,l.hi+.96]){let ex=l.horizontal?end:l.pos,ez=l.horizontal?l.pos:end;box(v,ex,l.height,ez,l.horizontal?.08:.18,.18,l.horizontal?.18:.08,[.22,.26,.3]);box(v,ex,l.height,ez,.1,.065,.1,[1,.12,.2])}}}
'''
s=s.replace('function update(dt)',helper+'\nfunction update(dt)',1)
s=s.replace('updateCameraSway(dt,Math.hypot(player.x-previousX', 'updateLasers(dt,previousX,previousY);if(player.hp<=0){finish(false);return}updateCameraSway(dt,Math.hypot(player.x-previousX',1)
s=s.replace('pickups.filter(o=>!o.used).forEach', 'renderLasers(v);pickups.filter(o=>!o.used).forEach',1)
s=s.replace('clone({world,enemies,pickups,doors,chairs,glassPanes,kills','clone({world,enemies,pickups,doors,chairs,glassPanes,lasers,kills',1)
s=s.replace('glassPanes=clone(snapshot.glassPanes);kills=', 'glassPanes=clone(snapshot.glassPanes);lasers=clone(snapshot.lasers||lasers);kills=',1)
p.write_text(s,encoding='utf-8')
p=Path('outputs/README.md');s=p.read_text(encoding='utf-8');s+='\nHazards tab: Sweeping laser ↔ spans east/west walls and slides north/south; Sweeping laser ↕ spans north/south walls and slides east/west. Place in a clear corridor with full-height walls on both beam ends. Emitters sweep the continuous matching corridor at 1.2 m/s, reversing at its ends, at 0.95 m height. Contact deals 15 damage with a 0.75-second cooldown. Crouch/crawl underneath or jump over. Obstructed placements without two wall anchors do not activate. Laser motion persists when revisiting a World Lab region.\n';p.write_text(s,encoding='utf-8')
